using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

// --- Configuration ---
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// --- Build the AI agent with tools ---
IChatClient chatClient = new OpenAI.OpenAIClient(openAiKey)
    .GetChatClient(model)
    .AsIChatClient();

var tools = new ResearchTools();

var agent = chatClient.AsAIAgent(
    instructions: """
        You are a research assistant. When given a topic you:
        1. Search the web for relevant information (make 2-3 searches with varied queries).
        2. Take notes on the key findings from each search.
        3. After gathering enough information, produce a concise summary that
           synthesizes your notes into a coherent overview with key facts and insights.
        Always search before summarizing. Always take notes on important findings.
        """,
    name: "ResearchAgent",
    description: "An AI agent that researches topics using web search and note-taking.",
    tools: [AIFunctionFactory.Create(tools.SearchWeb),
            AIFunctionFactory.Create(tools.TakeNote),
            AIFunctionFactory.Create(tools.GetNotes)]);

// --- Main interaction loop ---
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent (type 'exit' to quit)        ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

var session = new AgentSession();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var input = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(input))
        continue;
    if (input.Equals("exit", StringComparison.OrdinalIgnoreCase))
        break;

    tools.ClearNotes();

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching…");
    Console.ResetColor();

    try
    {
        // Start a fresh session per query so tool-call history doesn't accumulate
        session = new AgentSession();
        var response = await agent.RunAsync(
            $"Research the following topic and provide a summary: {input}", session);

        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine();
        Console.WriteLine(response.Text);
        Console.ResetColor();
        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }
}

Console.WriteLine("Goodbye!");

// ──────────────────────────────────────────────────────────────
// Tool implementations
// ──────────────────────────────────────────────────────────────
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private static readonly HttpClient Http = new();

    [Description("Search the web for information on a given query. Returns a list of result titles, snippets, and URLs.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.ForegroundColor = ConsoleColor.Yellow;
        Console.WriteLine($"  🔍 Searching: \"{query}\"");
        Console.ResetColor();

        try
        {
            // Use DuckDuckGo Instant Answer API (no key required)
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await Http.GetStringAsync(url);

            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var sb = new StringBuilder();

            // Abstract / instant answer
            var abstractText = root.GetProperty("AbstractText").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            var abstractUrl = root.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                sb.AppendLine($"## {abstractSource}");
                sb.AppendLine(abstractText);
                sb.AppendLine($"Source: {abstractUrl}");
                sb.AppendLine();
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                int count = 0;
                foreach (var topic in topics.EnumerateArray())
                {
                    if (count >= 5) break;
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var link = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        sb.AppendLine($"- {text}");
                        if (!string.IsNullOrWhiteSpace(link))
                            sb.AppendLine($"  URL: {link}");
                        count++;
                    }
                }
            }

            var result = sb.Length > 0 ? sb.ToString() : "No results found. Try a different query.";
            return result;
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try rephrasing the query.";
        }
    }

    [Description("Take a research note to remember an important finding. Use this to record key facts and insights during research.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.ForegroundColor = ConsoleColor.Magenta;
        Console.WriteLine($"  📝 Note #{_notes.Count} saved");
        Console.ResetColor();
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Retrieve all research notes taken so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes taken yet.";

        var sb = new StringBuilder();
        for (int i = 0; i < _notes.Count; i++)
            sb.AppendLine($"Note #{i + 1}: {_notes[i]}");
        return sb.ToString();
    }

    public void ClearNotes() => _notes.Clear();
}

