85. sealed class ResearchTools
86. {
87.     private readonly List<string> _notes = [];
88.     private static readonly HttpClient Http = new();
89. 
90.     [Description("Search the web for information on a given query. Returns a list of result titles, snippets, and URLs.")]
91.     public async Task<string> SearchWeb(
92.         [Description("The search query string")] string query)
93.     {
94.         Console.ForegroundColor = ConsoleColor.Yellow;
95.         Console.WriteLine($"  🔍 Searching: \"{query}\"");
96.         Console.ResetColor();
97. 
98.         try
99.         {
100.             // Use DuckDuckGo Instant Answer API (no key required)
101.             var encoded = WebUtility.UrlEncode(query);
102.             var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
103.             var json = await Http.GetStringAsync(url);
104. 
105.             using var doc = JsonDocument.Parse(json);
106.             var root = doc.RootElement;
107. 
108.             var sb = new StringBuilder();
109. 
110.             // Abstract / instant answer
111.             var abstractText = root.GetProperty("AbstractText").GetString();
112.             var abstractSource = root.GetProperty("AbstractSource").GetString();
113.             var abstractUrl = root.GetProperty("AbstractURL").GetString();
114.             if (!string.IsNullOrWhiteSpace(abstractText))
115.             {
116.                 sb.AppendLine($"## {abstractSource}");
117.                 sb.AppendLine(abstractText);
118.                 sb.AppendLine($"Source: {abstractUrl}");
119.                 sb.AppendLine();
120.             }
121. 
122.             // Related topics
123.             if (root.TryGetProperty("RelatedTopics", out var topics))
124.             {
125.                 int count = 0;
126.                 foreach (var topic in topics.EnumerateArray())
127.                 {
128.                     if (count >= 5) break;
129.                     var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
130.                     var link = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
131.                     if (!string.IsNullOrWhiteSpace(text))
132.                     {
133.                         sb.AppendLine($"- {text}");
134.                         if (!string.IsNullOrWhiteSpace(link))
135.                             sb.AppendLine($"  URL: {link}");
136.                         count++;
137.                     }
138.                 }
139.             }
140. 
141.             var result = sb.Length > 0 ? sb.ToString() : "No results found. Try a different query.";
142.             return result;
143.         }
144.         catch (Exception ex)
145.         {
146.             return $"Search failed: {ex.Message}. Try rephrasing the query.";
147.         }
148.     }
149. 
150.     [Description("Take a research note to remember an important finding. Use this to record key facts and insights during research.")]
151.     public string TakeNote(
152.         [Description("The note content to save")] string note)
153.     {
154.         _notes.Add(note);
155.         Console.ForegroundColor = ConsoleColor.Magenta;
156.         Console.WriteLine($"  📝 Note #{_notes.Count} saved");
157.         Console.ResetColor();
158.         return $"Note #{_notes.Count} saved successfully.";
159.     }
160. 
161.     [Description("Retrieve all research notes taken so far.")]
162.     public string GetNotes()
163.     {
164.         if (_notes.Count == 0)
165.             return "No notes taken yet.";
166. 
167.         var sb = new StringBuilder();
168.         for (int i = 0; i < _notes.Count; i++)
169.             sb.AppendLine($"Note #{i + 1}: {_notes[i]}");
170.         return sb.ToString();
171.     }
172. 
173.     public void ClearNotes() => _notes.Clear();
174. }
