 using System.ComponentModel;
 using System.Net;
 using System.Text;
 using System.Text.Json;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;

 // --- Configuration ---
 var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running.");

 var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

 // --- Build the AI agent with tools ---
 IChatClient chatClient = new OpenAI.OpenAIClient(openAiKey)
     .GetChatClient(model)
     .AsIChatClient();

 var tools = new ResearchTools();

 var agent = chatClient.AsAIAgent(
     instructions: """
         You are a research assistant. When given a topic you:
         1. Search the web for relevant information (make 2-3 searches with varied queries).
         2. Take notes on the key findings from each search.
         3. After gathering enough information, produce a concise summary that
            synthesizes your notes into a coherent overview with key facts and insights.
         Always search before summarizing. Always take notes on important findings.
         """,
     name: "ResearchAgent",
     description: "An AI agent that researches topics using web search and note-taking.",
     tools: [AIFunctionFactory.Create(tools.SearchWeb),
             AIFunctionFactory.Create(tools.TakeNote),
             AIFunctionFactory.Create(tools.GetNotes)]);

 // --- Main interaction loop ---
 Console.WriteLine("╔══════════════════════════════════════════╗");
 Console.WriteLine("║        AI Research Agent (type 'exit' to quit)        ║");
 Console.WriteLine("╚══════════════════════════════════════════╝");
 Console.WriteLine();

 while (true)
 {
     Console.ForegroundColor = ConsoleColor.Cyan;
     Console.Write("Research topic> ");
     Console.ResetColor();

     var input = Console.ReadLine()?.Trim();
     if (string.IsNullOrEmpty(input))
         continue;
     if (input.Equals("exit", StringComparison.OrdinalIgnoreCase))
         break;

     tools.ClearNotes();

     Console.ForegroundColor = ConsoleColor.DarkGray;
     Console.WriteLine("Researching…");
     Console.ResetColor();

     try
     {
         var response = await agent.RunAsync(
             $"Research the following topic and provide a summary: {input}");

         Console.ForegroundColor = ConsoleColor.Green;
         Console.WriteLine();
         Console.WriteLine(response.Text);
         Console.ResetColor();
         Console.WriteLine();
     }
     catch (Exception ex)
     {
         Console.ForegroundColor = ConsoleColor.Red;
